//! 🇺🇸 The token core (`src/token/`) against `apps/sdk/tests/vectors/service-account-token-v1.json`, byte for byte.
//!
//! The file is a verbatim copy of the monorepo's
//! `packages/security-module/test-vectors/service-account-token-v1.json`,
//! generated by the TypeScript reference. Every derived key, every signature
//! and both seals must match it exactly — a divergence here is a broken
//! token, not a flaky test.
//!
//! 🇧🇷 O núcleo do token (`src/token/`) contra `apps/sdk/tests/vectors/service-account-token-v1.json`, byte a byte.
//!
//! O arquivo é uma cópia literal do
//! `packages/security-module/test-vectors/service-account-token-v1.json` do
//! monorepo, gerado pela referência em TypeScript. Toda chave derivada, toda
//! assinatura e os dois selos precisam bater exatamente — uma divergência
//! aqui é token quebrado, não teste instável.

use std::path::PathBuf;

use base64::Engine as _;
use serde_json::Value;

use _secure::token::{self, Keys};

fn vectors() -> Value {
    let path: PathBuf =
        [env!("CARGO_MANIFEST_DIR"), "..", "tests", "vectors", "service-account-token-v1.json"].iter().collect();
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).expect("vector is valid JSON")
}

fn text(value: &Value) -> &str {
    value.as_str().expect("string")
}

fn b64url(value: &Value) -> Vec<u8> {
    base64::engine::general_purpose::URL_SAFE_NO_PAD.decode(text(value)).expect("base64url")
}

fn b64(value: &Value) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD.decode(text(value)).expect("base64")
}

fn unhex(value: &Value) -> Vec<u8> {
    let hex = text(value);
    (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect()
}

fn key_id(decoded: &token::Decoded) -> String {
    decoded.key_id.iter().fold(String::from("svc_"), |mut out, byte| {
        out.push_str(&format!("{byte:02x}"));
        out
    })
}

#[test]
fn constants_match_the_reference() {
    let constants = &vectors()["constants"];
    assert_eq!(text(&constants["token_prefix"]), token::PREFIX);
    assert_eq!(text(&constants["hkdf_salt"]).as_bytes(), token::SALT);
    assert_eq!(text(&constants["ml_dsa_context"]).as_bytes(), token::REQUEST_CONTEXT);
    assert_eq!(text(&constants["hybrid_seal_info"]).as_bytes(), _secure::hybrid::INFO);
}

#[test]
fn every_token_decodes_derives_and_signs_exactly() {
    for vector in vectors()["vectors"].as_array().expect("vectors") {
        let decoded = token::decode(text(&vector["token"])).expect("a vector token decodes");
        assert_eq!(key_id(&decoded), text(&vector["key_id"]));
        assert_eq!(decoded.seed.to_vec(), unhex(&vector["seed_hex"]));
        assert_eq!(decoded.workspace_id, text(&vector["workspace_id"]));
        let encoded = token::encode(&decoded.key_id, &decoded.seed[..], &decoded.workspace_id).unwrap();
        assert_eq!(encoded.as_str(), text(&vector["token"]));

        for (label, expected) in vector["hkdf_output_hex"].as_object().expect("hkdf outputs") {
            let derived: Vec<u8> = if label == "ml-kem-768" {
                token::derive::<64>(&decoded.seed[..], label).unwrap().to_vec()
            } else {
                token::derive::<32>(&decoded.seed[..], label).unwrap().to_vec()
            };
            assert_eq!(derived, unhex(expected), "hkdf {label}");
        }

        let keys = Keys::from_seed(&decoded.seed[..]).unwrap();
        let public = &vector["public_keys"];
        assert_eq!(keys.ed25519_public().to_vec(), b64url(&public["ed25519"]));
        assert_eq!(keys.mldsa65_public(), b64url(&public["ml_dsa_65"]).as_slice());
        assert_eq!(keys.kem().x25519_public().to_vec(), b64url(&public["x25519"]));
        assert_eq!(keys.kem().mlkem768_public(), b64url(&public["ml_kem_768"]).as_slice());

        for request in vector["requests"].as_array().expect("requests") {
            let base = text(&request["signature_base"]).as_bytes();
            let mut expected = b64(&request["ed25519_signature_b64"]);
            expected.extend(b64(&request["ml_dsa_65_signature_b64"]));
            let signature = keys.sign(base, true).unwrap();
            assert_eq!(signature, expected, "{} {}", text(&vector["name"]), text(&request["name"]));
            let header = text(&request["headers"]["Signature"]);
            assert_eq!(header, format!("diagnos=:{}:", base64::engine::general_purpose::STANDARD.encode(&signature)));
            assert!(token::verify(keys.ed25519_public(), keys.mldsa65_public(), base, &signature));
        }
    }
}

#[test]
fn every_invalid_token_fails_for_the_documented_reason() {
    for case in vectors()["invalid_tokens"].as_array().expect("invalid tokens") {
        let error = token::decode(text(&case["token"])).err().expect("an invalid token is refused");
        assert_eq!(error.code(), text(&case["reason"]), "{}", text(&case["name"]));
    }
}

#[test]
fn both_seals_open_with_the_derived_pair() {
    let all = vectors();
    let seals = &all["seals"];
    let owner = all["vectors"]
        .as_array()
        .expect("vectors")
        .iter()
        .find(|vector| text(&seals["session"]["aad"]).ends_with(&format!(":{}", text(&vector["key_id"]))))
        .expect("one vector owns the seals");
    let decoded = token::decode(text(&owner["token"])).unwrap();
    let keys = Keys::from_seed(&decoded.seed[..]).unwrap();
    let open = |seal: &Value| {
        let sealed = &seal["sealed"];
        keys.kem()
            .open(
                &b64url(&sealed["salt"]),
                &b64url(&sealed["nonce"]),
                &b64url(&sealed["ciphertext"]),
                text(&seal["aad"]).as_bytes(),
            )
            .expect("the vector seal opens")
            .to_vec()
    };
    assert_eq!(open(&seals["group_kek"]), unhex(&seals["group_kek"]["kek_hex"]));
    assert_eq!(open(&seals["session"]), text(&seals["session"]["plaintext_utf8"]).as_bytes());
}
